package com.bank.k8s;

// A worker node with free CPU (millicores), memory (MB), a taint, and a zone.
public class Node {
    private final String name;
    private int freeCpu;
    private int freeMem;
    private final String taint;  // e.g. "payments" or "" (none)
    private final String zone;
    private int podsFromWorkload; // how many pods of the current workload it holds

    public Node(String name, int freeCpu, int freeMem, String taint, String zone) {
        this.name = name;
        this.freeCpu = freeCpu;
        this.freeMem = freeMem;
        this.taint = taint;
        this.zone = zone;
    }
    public String getName() { return name; }
    public int getFreeCpu() { return freeCpu; }
    public int getFreeMem() { return freeMem; }
    public String getTaint(){ return taint; }
    public String getZone() { return zone; }
    public int getPodsFromWorkload() { return podsFromWorkload; }

    public void place(int cpu, int mem) {
        freeCpu -= cpu; freeMem -= mem; podsFromWorkload++;
    }
}
