package com.bank.k8s;

import java.util.Set;

// A pod's scheduling requirements.
public class PodSpec {
    private final String name;
    private final int cpuRequest;   // millicores
    private final int memRequest;   // MB
    private final Set<String> tolerations; // taints it can tolerate
    private final boolean spread;   // prefer spreading across zones/nodes

    public PodSpec(String name, int cpuRequest, int memRequest,
                   Set<String> tolerations, boolean spread) {
        this.name = name;
        this.cpuRequest = cpuRequest;
        this.memRequest = memRequest;
        this.tolerations = tolerations;
        this.spread = spread;
    }
    public String getName()        { return name; }
    public int getCpuRequest()     { return cpuRequest; }
    public int getMemRequest()     { return memRequest; }
    public Set<String> getTolerations() { return tolerations; }
    public boolean wantsSpread()   { return spread; }
}
