package com.bank.k8s;

import java.util.*;
import java.util.logging.Logger;

// The scheduler: FILTER nodes that fit, then SCORE to pick the best.
public class Scheduler {
    private static final Logger log = Logger.getLogger(Scheduler.class.getName());

    public Node schedule(PodSpec pod, List<Node> nodes) {
        // Phase 1: FILTER (predicates).
        List<Node> feasible = new ArrayList<>();
        for (Node n : nodes) {
            if (n.getFreeCpu() < pod.getCpuRequest() || n.getFreeMem() < pod.getMemRequest()) {
                log.info(() -> "  filter: " + n.getName() + " rejected (insufficient resources)");
                continue;
            }
            if (!n.getTaint().isEmpty() && !pod.getTolerations().contains(n.getTaint())) {
                log.info(() -> "  filter: " + n.getName() + " rejected (taint '" + n.getTaint()
                        + "' not tolerated)");
                continue;
            }
            feasible.add(n);
        }
        if (feasible.isEmpty()) {
            log.severe("No feasible node for pod " + pod.getName() + " -> Pending");
            return null;
        }
        // Phase 2: SCORE (priorities). Higher is better.
        Node best = null; int bestScore = Integer.MIN_VALUE;
        for (Node n : feasible) {
            int score = 0;
            // Prefer nodes with more free resources (balanced fit).
            score += (n.getFreeCpu() + n.getFreeMem()) / 100;
            // Spread: penalise nodes already holding this workload.
            if (pod.wantsSpread()) score -= n.getPodsFromWorkload() * 50;
            final Node fn = n; final int fs = score;
            log.info(() -> "  score: " + fn.getName() + " zone=" + fn.getZone() + " = " + fs);
            if (score > bestScore) { bestScore = score; best = n; }
        }
        best.place(pod.getCpuRequest(), pod.getMemRequest());
        final Node chosen = best;
        log.info(() -> "SCHEDULED " + pod.getName() + " -> " + chosen.getName()
                + " (zone " + chosen.getZone() + ")");
        return best;
    }
}
