package com.bank.k8s;

import java.util.*;
import java.util.logging.*;

public class SchedulerDemo {
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new K8sLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        Logger log = Logger.getLogger(SchedulerDemo.class.getName());
        Scheduler scheduler = new Scheduler();

        List<Node> nodes = new ArrayList<>(List.of(
                new Node("node-a", 2000, 4096, "",         "zone-1"),
                new Node("node-b", 2000, 4096, "",         "zone-2"),
                new Node("node-c", 2000, 4096, "payments", "zone-1"))); // tainted

        log.info("=== Schedule 3 transfer-service replicas (spread) ===");
        for (int i = 1; i <= 3; i++) {
            PodSpec replica = new PodSpec("transfer-" + i, 500, 1024, Set.of(), true);
            log.info("Scheduling " + replica.getName());
            scheduler.schedule(replica, nodes);
        }

        log.info("=== Schedule a sensitive payment pod (needs payments node) ===");
        PodSpec payment = new PodSpec("payment-1", 500, 1024, Set.of("payments"), false);
        scheduler.schedule(payment, nodes);
    }
}

