apiVersion: apps/v1
kind: Deployment
metadata: { name: transfer-service }
spec:
  replicas: 3
  template:
    spec:
      containers:
        - name: transfer-service
          image: registry.bank.local/transfer-service:1.2.0
          resources:
            requests: { cpu: "500m", memory: "1Gi" }   # drives scheduling
            limits:   { cpu: "1",    memory: "1.5Gi" } # caps runtime
      # spread replicas across zones for resilience
      topologySpreadConstraints:
        - maxSkew: 1
          topologyKey: topology.kubernetes.io/zone
          whenUnsatisfiable: DoNotSchedule
          labelSelector: { matchLabels: { app: transfer-service } }
---
